const APP_ICON_B64 = "data:image/png;base64,";
/**
 * PWA Handler Module for Notebook Campus Network
 * Manages Service Worker registration, PWA installation prompts, and network status notifications.
 */

let deferredPrompt = null;
let swRegistration = null;

export function initPWA() {
  initServiceWorker();
  initNetworkListeners();
  initInstallPrompt();
}

/**
 * Register Service Worker
 */
function initServiceWorker() {
  if (!('serviceWorker' in navigator)) {
    console.log('[PWA] Service Worker not supported in this browser.');
    return;
  }

  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register('/sw.js')
      .then((reg) => {
        swRegistration = reg;
        console.log('[PWA] Service Worker registered successfully:', reg.scope);

        // Check for updates
        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          if (!newWorker) return;

          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              showUpdateToast(newWorker);
            }
          });
        });
      })
      .catch((err) => {
        console.warn('[PWA] Service Worker registration failed:', err);
      });

    // Handle controller change (reloads page after update)
    let refreshing = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!refreshing) {
        refreshing = true;
        window.location.reload();
      }
    });
  });
}

/**
 * Handle beforeinstallprompt & appinstalled events
 */
function initInstallPrompt() {
  window.addEventListener('beforeinstallprompt', (e) => {
    // Prevent default browser banner
    e.preventDefault();
    deferredPrompt = e;

    console.log('[PWA] beforeinstallprompt event captured.');

    // Render install banner if user hasn't opted out or dismissed it in this session
    const neverShow = localStorage.getItem('pwa_never_show') === 'true';
    const dismissedSession = sessionStorage.getItem('pwa_dismissed') === 'true';

    if (!neverShow && !dismissedSession) {
      showInstallBanner();
    }

    // Enable any custom nav install buttons
    toggleNavInstallButtons(true);
  });

  window.addEventListener('appinstalled', () => {
    console.log('[PWA] Notebook App was installed successfully!');
    deferredPrompt = null;
    hideInstallBanner();
    toggleNavInstallButtons(false);
  });
}

/**
 * Trigger install prompt on user click
 */
export async function triggerInstallPrompt() {
  if (!deferredPrompt) {
    console.log('[PWA] No install prompt available or app already installed.');
    return;
  }

  deferredPrompt.prompt();
  const { outcome } = await deferredPrompt.userChoice;
  console.log(`[PWA] User response to install prompt: ${outcome}`);

  deferredPrompt = null;
  hideInstallBanner();
  toggleNavInstallButtons(false);
}

/**
 * Render/Show Install Toast Banner
 */
function showInstallBanner() {
  let banner = document.getElementById('pwa-install-banner');

  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'pwa-install-banner';
    banner.className = 'pwa-install-banner';
    banner.innerHTML = `
      <button id="pwa-close-x-btn" class="pwa-close-x" aria-label="Close modal" title="Not Now">
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
      </button>
      <div class="pwa-install-header">
        <img src="data:image/png;base64," alt="Notebook App Icon" class="pwa-app-icon" />
        <div class="pwa-install-header-text">
          <div class="pwa-install-title">Install Notebook App</div>
          <div class="pwa-install-subtitle">NITER Campus Network</div>
        </div>
      </div>
      <p class="pwa-install-desc">Add to home screen for instant updates and offline access.</p>
      <div class="pwa-install-footer">
        <button id="pwa-install-btn" class="btn-pwa-install">
          <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="3" y2="15"/></svg>
          <span>Install App</span>
        </button>
        <div class="pwa-secondary-links">
          <button id="pwa-dismiss-btn" class="btn-pwa-dismiss">Not Now</button>
          <span class="pwa-link-divider">•</span>
          <button id="pwa-never-btn" class="btn-pwa-never">Don't show again</button>
        </div>
      </div>
    `;

    document.body.appendChild(banner);

    // Event listeners
    document.getElementById('pwa-install-btn')?.addEventListener('click', () => {
      triggerInstallPrompt();
    });

    document.getElementById('pwa-close-x-btn')?.addEventListener('click', () => {
      sessionStorage.setItem('pwa_dismissed', 'true');
      hideInstallBanner();
    });

    document.getElementById('pwa-dismiss-btn')?.addEventListener('click', () => {
      sessionStorage.setItem('pwa_dismissed', 'true');
      hideInstallBanner();
    });

    document.getElementById('pwa-never-btn')?.addEventListener('click', () => {
      localStorage.setItem('pwa_never_show', 'true');
      hideInstallBanner();
    });
  }

  // Delay slightly for smooth entrance animation
  setTimeout(() => {
    banner.classList.add('visible');
  }, 800);
}

function hideInstallBanner() {
  const banner = document.getElementById('pwa-install-banner');
  if (banner) {
    banner.classList.remove('visible');
  }
}

function toggleNavInstallButtons(show) {
  const btns = document.querySelectorAll('.pwa-nav-install-btn');
  btns.forEach((btn) => {
    btn.style.display = show ? 'inline-flex' : 'none';
  });
}

/**
 * Handle Network Offline/Online Status
 */
function initNetworkListeners() {
  let offlineBanner = document.getElementById('pwa-offline-banner');

  if (!offlineBanner) {
    offlineBanner = document.createElement('div');
    offlineBanner.id = 'pwa-offline-banner';
    offlineBanner.className = 'pwa-offline-banner';
    document.body.appendChild(offlineBanner);
  }

  function updateStatus() {
    if (!navigator.onLine) {
      offlineBanner.className = 'pwa-offline-banner visible';
      offlineBanner.innerHTML = `<span class="pwa-status-dot"></span> You are currently offline. Showing cached campus content.`;
    } else {
      if (offlineBanner.classList.contains('visible')) {
        offlineBanner.className = 'pwa-offline-banner visible online';
        offlineBanner.innerHTML = `<span class="pwa-status-dot"></span> Back online! Connection restored.`;
        setTimeout(() => {
          offlineBanner.classList.remove('visible');
        }, 3000);
      }
    }
  }

  window.addEventListener('online', updateStatus);
  window.addEventListener('offline', updateStatus);

  // Check initial state if offline
  if (!navigator.onLine) {
    updateStatus();
  }
}

/**
 * Show App Update Toast when a new SW version is waiting
 */
function showUpdateToast(worker) {
  let banner = document.getElementById('pwa-update-toast');
  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'pwa-update-toast';
    banner.className = 'pwa-install-banner visible';
    banner.style.borderColor = 'var(--accent)';
    banner.innerHTML = `
      <img src="data:image/png;base64," alt="Notebook Icon" class="pwa-app-icon" />
      <div class="pwa-install-content">
        <div class="pwa-install-title">New Version Available</div>
        <div class="pwa-install-desc">An update for Notebook is ready. Refresh to update now.</div>
        <div class="pwa-install-actions">
          <button id="pwa-update-btn" class="btn-pwa-install">Update Now</button>
        </div>
      </div>
    `;
    document.body.appendChild(banner);

    document.getElementById('pwa-update-btn')?.addEventListener('click', () => {
      worker.postMessage({ type: 'SKIP_WAITING' });
    });
  }
}
